    exit 1
fi

# Map app names to container IDs
case "$APP" in
    portainer)        VMID=100 ;;
    network-services) VMID=101 ;;
    traefik)          VMID=200 ;;
    dashboards)       VMID=201 ;;
    authelia)         VMID=202 ;;
    immich)           VMID=304 ;;
    openwebui)        VMID=501 ;;
    *)
        echo "Unknown app: $APP"
        exit 1
        ;;
esac

