input.new_string:
#!/usr/bin/env bash
# Backup a single app container
# Usage: ./scripts/backup/backup-app.sh <app>

set -eo pipefail

APP="${1:-}"

if [[ -z "$APP" ]]; then
    echo "Usage: $0 <app>"
    echo "Apps: portainer, network-services, traefik, dashboards, authelia,"
    echo "      immich, immich-importer, jellyfin, media-management,"
    echo "      monitoring, openwebui, n8n"
    exit 1
fi

# Map app names to container IDs
case "$APP" in
    portainer)         VMID=100 ;;
    network-services)  VMID=101 ;;
    traefik)           VMID=200 ;;
    dashboards)        VMID=201 ;;
    authelia)          VMID=202 ;;
    immich-importer)   VMID=303 ;;
    immich)            VMID=304 ;;
    jellyfin)          VMID=401 ;;
    media-management)  VMID=402 ;;
    monitoring)        VMID=500 ;;
    openwebui)         VMID=501 ;;
    n8n)               VMID=502 ;;
    *)
        echo "Unknown app: $APP"
        exit 1
        ;;
esac

echo "Starting backup for $APP (Container $VMID)..."
ssh root@homelab "vzdump $VMID --storage backup-tank --mode snapshot --compress zstd --script /var/lib/vz/snippets/pre-backup-hook.sh"

