#!/usr/bin/env bash
# Backup a single app container
# Usage: ./scripts/backup/backup-app.sh <app>

set -eo pipefail

APP="${1:-}"

if [[ -z "$APP" ]]; then
    echo "Usage: $0 <app>"
    echo "Apps: portainer, network-services, traefik, dashboards, authelia,"
    echo "      immich, jellyfin, media-management, monitoring, openwebui, n8n"
    exit 1
fi

# Map app names to container IDs
# Note: immich-importer (303) and desktop-tmp (600) are excluded - stateless/temporary
case "$APP" in
    portainer)         VMID=100 ;;
    network-services)  VMID=101 ;;
    traefik)           VMID=200 ;;
    dashboards)        VMID=201 ;;
    authelia)          VMID=202 ;;
    immich)            VMID=304 ;;
    jellyfin)          VMID=401 ;;
    media-management)  VMID=402 ;;
    monitoring)        VMID=500 ;;
    openwebui)         VMID=501 ;;
    n8n)               VMID=502 ;;
