  value       = proxmox_virtual_environment_container.lxc.ipv4
}

output "node_name" {
  description = "The Proxmox node name"
  value       = var.proxmox_node
}

output "ssh_command" {
  description = "SSH connection command"
  value       = "ssh root@${try(proxmox_virtual_environment_container.lxc.ipv4["eth0"], "PENDING_IP")}"
  depends_on  = [time_sleep.wait_for_ip]
}

